// Telegram sends voice as .oga, audio as .mp3/.m4a, video as .mp4.
// Give every file a name + type that Groq Whisper accepts.
const msg = $('Telegram Trigger').first().json.message || {};
const allowed = ['flac', 'mp3', 'mp4', 'mpeg', 'mpga', 'm4a', 'ogg', 'wav', 'webm'];
const mimes = { ogg: 'audio/ogg', mp3: 'audio/mpeg', mpeg: 'audio/mpeg', mpga: 'audio/mpeg', mp4: 'video/mp4', m4a: 'audio/mp4', wav: 'audio/wav', flac: 'audio/flac', webm: 'audio/webm' };
const items = $input.all();
for (const item of items) {
  if (!item.binary || !item.binary.data) continue;
  const bin = item.binary.data;
  let ext = String(bin.fileExtension || (bin.fileName || '').split('.').pop() || '').toLowerCase();
  if (ext === 'oga' || ext === 'opus') ext = 'ogg';
  if (!allowed.includes(ext)) {
    if (msg.voice) ext = 'ogg';
    else if (msg.video || msg.video_note) ext = 'mp4';
    else ext = 'mp3';
  }
  bin.fileName = 'audio.' + ext;
  bin.fileExtension = ext;
  bin.mimeType = mimes[ext];
}
return items;

// Convert the downloaded Telegram photo to base64 and build the vision prompt.
const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
const meta = $input.first().binary.data;
const mime = (meta.mimeType && meta.mimeType.startsWith('image/')) ? meta.mimeType : 'image/jpeg';
const caption = (($('Telegram Trigger').first().json.message.caption) || '').trim();
const prompt = (caption ? 'The user sent this photo with the message: ' + caption + '\n\n' : '')
  + 'Describe the photo in detail. If it contains any text, read it out exactly. If the user asked a question, answer it.';
return [{ json: { image_b64: buf.toString('base64'), mime_type: mime, caption: caption, vision_prompt: prompt } }];

// Decide what kind of file was sent and fix its binary info so the next nodes can read it.
const msg = $('Telegram Trigger').first().json.message || {};
const doc = msg.document || {};
const fileName = doc.file_name || 'file';
const mime = String(doc.mime_type || '').toLowerCase();
const ext = fileName.includes('.') ? fileName.split('.').pop().toLowerCase() : '';

const TEXT_EXT = ['txt', 'md', 'markdown', 'csv', 'tsv', 'json', 'jsonl', 'xml', 'html', 'htm', 'css', 'js', 'mjs', 'ts', 'jsx', 'tsx', 'py', 'java', 'c', 'cpp', 'h', 'cs', 'go', 'rs', 'rb', 'php', 'sql', 'sh', 'bat', 'ps1', 'yaml', 'yml', 'toml', 'ini', 'cfg', 'conf', 'env', 'log', 'srt', 'vtt', 'tex', 'ics', 'vcf'];
const IMG_MIME = { jpg: 'image/jpeg', jpeg: 'image/jpeg', png: 'image/png', webp: 'image/webp' };

let kind = 'other';
if (ext === 'pdf' || mime === 'application/pdf') kind = 'pdf';
else if (ext === 'docx' || ext === 'pptx' || mime.includes('wordprocessingml.document') || mime.includes('presentationml.presentation')) kind = 'office';
else if (['xlsx', 'xls', 'xlsm', 'ods'].includes(ext) || mime.includes('spreadsheetml') || mime === 'application/vnd.ms-excel' || mime.includes('opendocument.spreadsheet')) kind = 'sheet';
else if (IMG_MIME[ext] || ['image/jpeg', 'image/png', 'image/webp'].includes(mime)) kind = 'image';
else if (TEXT_EXT.includes(ext) || mime.startsWith('text/') || mime === 'application/json' || mime === 'application/xml') kind = 'text';

return $input.all().map(item => {
  const bin = item.binary && item.binary.data;
  if (bin) {
    bin.fileName = fileName;
    if (kind === 'office') { bin.fileExtension = 'zip'; bin.mimeType = 'application/zip'; }   // docx/pptx are zip files
    else if (kind === 'sheet') { bin.fileExtension = ext || 'xlsx'; }
    else if (kind === 'image') { bin.mimeType = IMG_MIME[ext] || mime || 'image/jpeg'; }
  }
  return { json: { kind, ext, file_name: fileName, mime_type: mime, caption: msg.caption || '' }, binary: item.binary };
});

// Turns the extracted file content into one text message for the AI agent.
const MAX_CHARS = 10000; // raise this if your Groq plan allows more tokens per minute
const info = $('Classify Document').first().json;
const items = $input.all();
const first = items[0] || { json: {} };
let text = '';
let note = '';

const xmlToText = (xml) => xml
  .replace(/<w:tab\s*\/>/g, '\t')
  .replace(/<\/w:tc>/g, '\t')
  .replace(/<\/w:p>|<\/a:p>|<w:br\s*\/>|<a:br\s*\/>/g, '\n')
  .replace(/<[^>]+>/g, '')
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&apos;/g, "'").replace(/&amp;/g, '&')
  .replace(/[ \t]+\n/g, '\n').replace(/\n{3,}/g, '\n\n').trim();

try {
  if (info.kind === 'pdf') {
    if (first.json.error) {
      note = 'The PDF could not be opened (it may be damaged or password protected).';
    } else {
      const t = first.json.text;
      text = Array.isArray(t) ? t.join('\n') : String(t ?? '');
      if (!text.trim()) note = 'No readable text was found. It is probably a scanned or image-only PDF.';
    }
  } else if (info.kind === 'office') {
    const bin = first.binary || {};
    const parts = [];
    for (const key of Object.keys(bin)) {
      const b = bin[key];
      const full = ((b.directory ? b.directory + '/' : '') + (b.fileName || '')).replace(/^\/+/, '');
      const slide = full.match(/^ppt\/slides\/slide(\d+)\.xml$/);
      if (full === 'word/document.xml' || slide) {
        const buf = await this.helpers.getBinaryDataBuffer(0, key);
        parts.push({ n: slide ? Number(slide[1]) : 0, isSlide: !!slide, xml: buf.toString('utf8') });
      }
    }
    parts.sort((a, b) => a.n - b.n);
    text = parts.map(p => (p.isSlide ? 'Slide ' + p.n + ':\n' : '') + xmlToText(p.xml)).join('\n\n');
    if (!text.trim()) note = 'No readable text was found in this Word/PowerPoint file.';
  } else if (info.kind === 'sheet') {
    const rows = items.map(i => i.json).filter(r => r && !r.error && Object.keys(r).length > 0);
    if (first.json && first.json.error) {
      note = 'The spreadsheet could not be opened.';
    } else if (rows.length === 0) {
      note = 'The first sheet of this spreadsheet is empty.';
    } else {
      const headers = Object.keys(rows[0]);
      text = 'Columns: ' + headers.join(' | ') + '\nTotal rows: ' + rows.length + '\n'
        + rows.map(r => headers.map(h => (r[h] ?? '')).join(' | ')).join('\n');
    }
  } else if (info.kind === 'text') {
    const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
    text = buf.toString('utf8');
    if (!text.trim()) note = 'The file is empty.';
  } else {
    note = 'This file type (' + (info.ext || 'unknown') + ') cannot be read. Supported: PDF, Word (.docx), PowerPoint (.pptx), Excel/ODS, images, and text/code files (txt, md, csv, json, xml, html, py, js ...). Old .doc/.ppt files should be saved as .docx/.pptx or PDF first.';
  }
} catch (e) {
  note = 'Reading the file failed: ' + e.message;
}

let body = text.trim();
const total = body.length;
const truncated = total > MAX_CHARS;
if (truncated) body = body.slice(0, MAX_CHARS);

const lines = [
  '[DOCUMENT MESSAGE]',
  'File name: ' + info.file_name,
  'File type: ' + (info.ext || info.kind),
  'User caption: ' + (info.caption || '(none)'),
  ''
];
if (note) {
  lines.push('Problem: ' + note);
} else {
  lines.push('Extracted content' + (truncated ? ' (TRUNCATED: only the first ' + MAX_CHARS + ' of ' + total + ' characters are shown)' : '') + ':');
  lines.push(body);
}
lines.push('', 'Reply to the user naturally based on this. If there is no caption, give a short summary of the file and offer to answer questions about it.');
return [{ json: { user_text: lines.join('\n') } }];

// Saves every sticker the user sends (so the bot can send stickers back later)
// and passes the sticker to the AI agent as text.
const s = ($input.first().json.message || {}).sticker || {};
const emoji = String(s.emoji || '').replace(/\uFE0F/g, '').trim();
const store = $getWorkflowStaticData('global');
if (!store.stickers) store.stickers = {};
if (emoji && s.file_id) {
  const list = store.stickers[emoji] || [];
  if (!list.includes(s.file_id)) list.push(s.file_id);
  store.stickers[emoji] = list.slice(-10); // keep the newest 10 per emoji
}
const text = '[STICKER MESSAGE]\nThe user sent a sticker with the emoji: ' + (s.emoji || '(none)')
  + (s.set_name ? '\nSticker pack: ' + s.set_name : '')
  + '\n\nReply to the user naturally and shortly, like a friend would. Match the mood of the sticker.';
return [{ json: { user_text: text } }];

// Splits the agent answer into the reply text and an optional sticker.
// The agent asks for a sticker by ending its answer with a tag like [sticker:😂].
// Stickers are learned automatically: every sticker you send to the bot is saved by the "Sticker Input" node.
const CHANCE = 0.8; // chance that a requested sticker is really sent (keeps stickers occasional)
const store = $getWorkflowStaticData('global');
const lib = store.stickers || {};
const raw = String($input.first().json.output ?? '');
const norm = (e) => String(e || '').replace(/\uFE0F/g, '').trim();

// emojis that feel alike: if no sticker exists for the exact emoji, one from the same group is used
const GROUPS = [
  ['😂', '🤣', '😆', '😄', '😀', '😁', '😃', '😊', '🙂', '😎', '😅'],
  ['❤', '😍', '🥰', '😘', '💖', '💕', '😚', '☺'],
  ['😢', '😭', '😔', '😞', '🥺', '😥', '☹', '🙁'],
  ['👍', '👌', '🙌', '👏', '💪', '✅', '🔥', '🎉'],
  ['😮', '😲', '😱', '🤯', '😳'],
  ['🤔', '🧐', '🤨', '😐'],
  ['😴', '😪', '🥱'],
  ['👋', '🤗', '🙏'],
  ['😡', '😠', '🤬', '😤']
].map(g => g.map(norm));

const tag = raw.match(/\[sticker:\s*([^\]]+?)\s*\]/i);
let text = raw.replace(/\[sticker:[^\]]*\]/gi, '').trim();
if (!text) text = '🙂';

let sticker_id = '';
if (tag && Math.random() < CHANCE) {
  const want = norm(tag[1]);
  let pool = (lib[want] && lib[want].length) ? lib[want] : null;
  if (!pool) {
    const group = GROUPS.find(g => g.includes(want));
    if (group) {
      const all = [];
      for (const e of group) { if (lib[e]) all.push(...lib[e]); }
      if (all.length) pool = all;
    }
  }
  if (pool) sticker_id = pool[Math.floor(Math.random() * pool.length)];
}
return [{ json: { text: text.slice(0, 4000), sticker_id: sticker_id, sticker_wanted: tag ? norm(tag[1]) : '' } }];

// Reminder store: add / list / cancel. Data is kept in workflow static data.
const TZ_OFFSET_MIN = 330; // IST = UTC+05:30. Change if you use another timezone.
const store = $getWorkflowStaticData('global');
if (!Array.isArray(store.reminders)) store.reminders = [];
if (!store.counter) store.counter = 0;

const fmt = (ms) => {
  const d = new Date(ms + TZ_OFFSET_MIN * 60000);
  const months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  let h = d.getUTCHours();
  const m = String(d.getUTCMinutes()).padStart(2, '0');
  const ap = h >= 12 ? 'PM' : 'AM';
  h = h % 12 || 12;
  return d.getUTCDate() + ' ' + months[d.getUTCMonth()] + ' ' + d.getUTCFullYear() + ', ' + h + ':' + m + ' ' + ap;
};

const b = $input.first().json.body || {};
const action = String(b.action || '').toLowerCase();
const chatId = String(b.chat_id || '');
if (!chatId) return [{ json: { ok: false, error: 'chat_id missing' } }];

if (action === 'add') {
  // accept "2026-11-22 19:00:00" as well as "2026-11-22T19:00:00"
  let s = String(b.remind_at || '').trim().replace(/^(\d{4}-\d{2}-\d{2})\s+/, '$1T').replace(/\s+/g, '');
  if (!s) return [{ json: { ok: false, error: 'remind_at missing' } }];
  const hasTz = s.endsWith('Z') || /[+-]\d{2}:?\d{2}$/.test(s);
  if (!hasTz) {
    const sign = TZ_OFFSET_MIN >= 0 ? '+' : '-';
    const a = Math.abs(TZ_OFFSET_MIN);
    s += sign + String(Math.floor(a / 60)).padStart(2, '0') + ':' + String(a % 60).padStart(2, '0');
  }
  const ms = new Date(s).getTime();
  if (isNaN(ms)) return [{ json: { ok: false, error: 'Invalid remind_at date-time. Use ISO 8601 like 2026-11-22T19:00:00+05:30' } }];
  if (ms < Date.now() - 60000) return [{ json: { ok: false, error: 'That time is already in the past. Use a future time.' } }];
  const message = String(b.message || 'Reminder');
  // the agent may retry the same call: do not create a duplicate
  const dup = store.reminders.find(r => r.chat_id === chatId && r.remind_at_ms === ms && r.message === message);
  if (dup) return [{ json: { ok: true, id: dup.id, message: dup.message, remind_at: fmt(dup.remind_at_ms), note: 'already scheduled' } }];
  const id = ++store.counter;
  store.reminders.push({ id: id, chat_id: chatId, message: message, remind_at_ms: ms });
  return [{ json: { ok: true, id: id, message: message, remind_at: fmt(ms) } }];
}

if (action === 'list') {
  const mine = store.reminders
    .filter(r => r.chat_id === chatId)
    .sort((x, y) => x.remind_at_ms - y.remind_at_ms);
  return [{ json: { ok: true, count: mine.length, reminders: mine.map(r => ({ id: r.id, message: r.message, remind_at: fmt(r.remind_at_ms) })) } }];
}

if (action === 'cancel') {
  const rid = String(b.reminder_id || '').trim().toLowerCase();
  const before = store.reminders.length;
  if (rid === 'all') {
    store.reminders = store.reminders.filter(r => r.chat_id !== chatId);
  } else {
    store.reminders = store.reminders.filter(r => !(r.chat_id === chatId && String(r.id) === rid));
  }
  const removed = before - store.reminders.length;
  return [{ json: { ok: removed > 0, cancelled: removed, error: removed > 0 ? undefined : 'No matching reminder found for that ID' } }];
}

return [{ json: { ok: false, error: 'Unknown action' } }];

// Runs every minute: pick reminders that are due and remove them from the store.
const store = $getWorkflowStaticData('global');
if (!Array.isArray(store.reminders) || store.reminders.length === 0) return [];
const now = Date.now();
const due = store.reminders.filter(r => r.remind_at_ms <= now);
if (due.length === 0) return [];
store.reminders = store.reminders.filter(r => r.remind_at_ms > now);
return due.map(r => ({ json: { chat_id: r.chat_id, message: r.message } }));
